n = int(input())
cs = {}
for i in range(n):
    a, c = map(int, input().split())
    if c in cs:
        cs[c] = min(cs[c], a)
    else:
        cs[c] = a

max_min_deliciousness = 0
best_color = -1
for k in cs:
    m = cs[k]
    if m > max_min_deliciousness:
        best_color = k
        max_min_deliciousness = m

print(best_color)
